import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { supportAPI } from '../utils/api';
import { toast } from 'react-toastify';

const STATUS_COLORS = { open: '#00b894', closed: '#9e9e9e' };

export default function Support() {
  const { user } = useAuth();
  const [view, setView]       = useState('list'); // 'list' | 'new' | 'ticket'
  const [tickets, setTickets] = useState([]);
  const [active, setActive]   = useState(null);
  const [loading, setLoading] = useState(false);
  const [replyText, setReplyText] = useState('');
  const [form, setForm] = useState({ name: user?.name || '', email: user?.email || '', subject: '', message: '' });
  const [submitting, setSubmitting] = useState(false);
  const bottomRef = useRef(null);

  useEffect(() => {
    if (user) loadTickets();
  }, [user]);

  useEffect(() => {
    if (active) bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [active?.messages?.length]);

  const loadTickets = async () => {
    if (!user) return;
    setLoading(true);
    try {
      const { data } = await supportAPI.getMine();
      setTickets(data);
    } catch {}
    setLoading(false);
  };

  const openTicket = async (t) => {
    try {
      const { data } = await supportAPI.getTicket(t._id);
      setActive(data);
      setView('ticket');
    } catch { toast.error('Failed to load ticket'); }
  };

  const submitNew = async (e) => {
    e.preventDefault();
    if (!form.subject.trim() || !form.message.trim()) return toast.error('Subject and message are required');
    setSubmitting(true);
    try {
      const { data } = await supportAPI.create(form);
      setTickets(prev => [data, ...prev]);
      setActive(data);
      setView('ticket');
      toast.success('Ticket created! We\'ll respond soon 🙌');
    } catch (err) { toast.error(err.response?.data?.message || 'Failed to create ticket'); }
    setSubmitting(false);
  };

  const sendReply = async () => {
    if (!replyText.trim()) return;
    try {
      const { data } = await supportAPI.sendMessage(active._id, replyText.trim());
      setActive(data);
      setTickets(prev => prev.map(t => t._id === data._id ? { ...t, updatedAt: data.updatedAt } : t));
      setReplyText('');
      setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: 'smooth' }), 60);
    } catch { toast.error('Failed to send message'); }
  };

  return (
    <div className="container" style={{ maxWidth: 860, padding: '40px 20px', minHeight: '70vh' }}>
      {/* Breadcrumb / header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 28, flexWrap: 'wrap' }}>
        {view !== 'list' && (
          <button onClick={() => { setView('list'); setActive(null); loadTickets(); }}
            style={{ background: 'none', border: 'none', color: '#6c63ff', fontWeight: 700, fontSize: 14, cursor: 'pointer', padding: '6px 14px', borderRadius: 10, border: '2px solid #e0e0ff' }}>
            ← Back to Tickets
          </button>
        )}
        <h1 style={{ fontSize: 'clamp(20px,3vw,26px)', fontWeight: 800, margin: 0 }}>
          {view === 'list' ? '🎧 Support Center' : view === 'new' ? '📝 New Ticket' : `🎫 ${active?.subject}`}
        </h1>
        {view === 'list' && (
          <button className="btn btn-primary" onClick={() => setView('new')} style={{ marginLeft: 'auto', padding: '10px 22px' }}>
            + New Ticket
          </button>
        )}
      </div>

      {/* List view */}
      {view === 'list' && (
        <div>
          {loading ? (
            <div style={{ textAlign: 'center', padding: 50, color: '#636e72' }}>Loading your tickets...</div>
          ) : !user ? (
            <div style={{ textAlign: 'center', padding: 50 }}>
              <div style={{ fontSize: 50, marginBottom: 12 }}>🔐</div>
              <p style={{ color: '#636e72', marginBottom: 16 }}>Please log in to view your support tickets.</p>
            </div>
          ) : tickets.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px' }}>
              <div style={{ fontSize: 56, marginBottom: 12 }}>🎧</div>
              <h2 style={{ fontWeight: 700, fontSize: 20, marginBottom: 8 }}>No tickets yet</h2>
              <p style={{ color: '#636e72', marginBottom: 24 }}>Have a question or issue? Create a support ticket and we'll get back to you.</p>
              <button className="btn btn-primary" onClick={() => setView('new')}>Create First Ticket</button>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {tickets.map(t => (
                <div key={t._id} onClick={() => openTicket(t)}
                  style={{ background: 'white', borderRadius: 16, padding: '18px 22px', border: '2px solid #f0f0f0', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 16, transition: 'all 0.2s', boxShadow: '0 2px 10px rgba(0,0,0,0.04)' }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = '#6c63ff'; e.currentTarget.style.boxShadow = '0 4px 20px rgba(108,99,255,0.1)'; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = '#f0f0f0'; e.currentTarget.style.boxShadow = '0 2px 10px rgba(0,0,0,0.04)'; }}>
                  <div style={{ fontSize: 28, flexShrink: 0 }}>🎫</div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 3 }}>{t.subject}</div>
                    <div style={{ fontSize: 12, color: '#9e9e9e' }}>
                      {t.messages?.length || 0} message{t.messages?.length !== 1 ? 's' : ''} · Updated {new Date(t.updatedAt).toLocaleDateString('en-IN', { dateStyle: 'medium' })}
                    </div>
                  </div>
                  <span style={{ background: STATUS_COLORS[t.status] + '20', color: STATUS_COLORS[t.status], fontWeight: 700, padding: '4px 12px', borderRadius: 20, fontSize: 12, flexShrink: 0 }}>
                    {t.status === 'open' ? '🟢 Open' : '⚫ Closed'}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* New ticket form */}
      {view === 'new' && (
        <div style={{ background: 'white', borderRadius: 24, padding: 32, boxShadow: '0 4px 20px rgba(108,99,255,0.08)', border: '1px solid #e0e0ff' }}>
          <form onSubmit={submitNew}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
              <div className="form-group">
                <label className="form-label">Your Name *</label>
                <input className="form-input" value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required />
              </div>
              <div className="form-group">
                <label className="form-label">Email *</label>
                <input className="form-input" type="email" value={form.email} onChange={e => setForm(f => ({ ...f, email: e.target.value }))} required readOnly={!!user} style={user ? { background: '#f8f7ff' } : {}} />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">Subject *</label>
              <input className="form-input" placeholder="e.g. My order hasn't arrived yet" value={form.subject} onChange={e => setForm(f => ({ ...f, subject: e.target.value }))} required />
            </div>
            <div className="form-group">
              <label className="form-label">Message *</label>
              <textarea className="form-input" rows={6} placeholder="Describe your issue in detail…" value={form.message} onChange={e => setForm(f => ({ ...f, message: e.target.value }))} required style={{ resize: 'vertical', minHeight: 120 }} />
            </div>
            <div style={{ display: 'flex', gap: 12 }}>
              <button type="button" className="btn btn-secondary" onClick={() => setView('list')}>Cancel</button>
              <button type="submit" className="btn btn-primary" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit Ticket'}</button>
            </div>
          </form>
        </div>
      )}

      {/* Ticket conversation view */}
      {view === 'ticket' && active && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 0, background: 'white', borderRadius: 24, overflow: 'hidden', boxShadow: '0 4px 20px rgba(0,0,0,0.08)', border: '1px solid #e0e0f0' }}>
          {/* Info bar */}
          <div style={{ background: '#f8f7ff', padding: '14px 22px', borderBottom: '1px solid #e0e0f0', display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 12, color: '#9e9e9e' }}>Ticket · {new Date(active.createdAt).toLocaleDateString('en-IN', { dateStyle: 'long' })}</div>
            </div>
            <span style={{ background: STATUS_COLORS[active.status] + '20', color: STATUS_COLORS[active.status], fontWeight: 700, padding: '4px 14px', borderRadius: 20, fontSize: 12 }}>
              {active.status === 'open' ? '🟢 Open' : '⚫ Closed'}
            </span>
          </div>

          {/* Messages */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '20px', display: 'flex', flexDirection: 'column', gap: 14, maxHeight: 420 }}>
            {active.messages?.map((m, i) => {
              const isUser = m.sender === 'user';
              return (
                <div key={i} style={{ display: 'flex', justifyContent: isUser ? 'flex-end' : 'flex-start' }}>
                  <div style={{ maxWidth: '80%' }}>
                    <div style={{ padding: '10px 16px', borderRadius: isUser ? '18px 18px 4px 18px' : '18px 18px 18px 4px', background: isUser ? 'linear-gradient(135deg,#6c63ff,#a29bfe)' : '#f5f5f5', color: isUser ? 'white' : '#212121', fontSize: 14, lineHeight: 1.6, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                      {m.text}
                    </div>
                    <div style={{ fontSize: 10, color: '#bdbdbd', marginTop: 4, textAlign: isUser ? 'right' : 'left', paddingLeft: isUser ? 0 : 4 }}>
                      {isUser ? 'You' : 'Support'} · {new Date(m.createdAt).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
                    </div>
                  </div>
                </div>
              );
            })}
            <div ref={bottomRef} />
          </div>

          {/* Reply box */}
          {active.status === 'open' ? (
            <div style={{ borderTop: '1px solid #f0f0f0', padding: '14px 20px', display: 'flex', gap: 10, alignItems: 'flex-end' }}>
              <textarea
                value={replyText}
                onChange={e => setReplyText(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendReply(); } }}
                placeholder="Type your reply… (Enter to send)"
                rows={2}
                style={{ flex: 1, resize: 'none', border: '1.5px solid #e0e0e0', borderRadius: 12, padding: '10px 14px', fontSize: 14, fontFamily: 'inherit', outline: 'none', lineHeight: 1.5 }}
              />
              <button onClick={sendReply} disabled={!replyText.trim()} className="btn btn-primary" style={{ padding: '10px 18px', flexShrink: 0 }}>
                Send
              </button>
            </div>
          ) : (
            <div style={{ padding: '14px 20px', background: '#f5f5f5', textAlign: 'center', fontSize: 13, color: '#9e9e9e' }}>
              This ticket is closed. <button style={{ background: 'none', border: 'none', color: '#6c63ff', fontWeight: 700, cursor: 'pointer' }} onClick={() => setView('new')}>Open a new ticket</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
