import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { productAPI } from '../utils/api';
import { useCart } from '../context/CartContext';
import { toast } from 'react-toastify';

function useInView(threshold = 0.15) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVisible(true); obs.disconnect(); } }, { threshold });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, visible];
}

function CountdownTimer({ endsAt }) {
  const [timeLeft, setTimeLeft] = useState({});
  useEffect(() => {
    const calc = () => {
      const diff = new Date(endsAt) - new Date();
      if (diff <= 0) return setTimeLeft({ expired: true });
      const d = Math.floor(diff / 86400000);
      const h = Math.floor((diff % 86400000) / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      setTimeLeft({ d, h, m, s });
    };
    calc();
    const t = setInterval(calc, 1000);
    return () => clearInterval(t);
  }, [endsAt]);

  if (timeLeft.expired) return <span style={{ color: '#d63031', fontWeight: 700, fontSize: 12 }}>Expired</span>;
  return (
    <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
      {timeLeft.d > 0 && <><span style={boxStyle}>{timeLeft.d}d</span></>}
      <span style={boxStyle}>{String(timeLeft.h).padStart(2,'0')}h</span>
      <span style={{ color: '#c2185b', fontWeight: 700 }}>:</span>
      <span style={boxStyle}>{String(timeLeft.m).padStart(2,'0')}m</span>
      <span style={{ color: '#c2185b', fontWeight: 700 }}>:</span>
      <span style={boxStyle}>{String(timeLeft.s).padStart(2,'0')}s</span>
    </div>
  );
}
const boxStyle = { background: '#fce4ec', color: '#c2185b', fontWeight: 800, fontSize: 13, padding: '2px 6px', borderRadius: 6, minWidth: 28, textAlign: 'center' };

export default function SpecialOffers() {
  const [offers, setOffers] = useState([]);
  const [loading, setLoading] = useState(true);
  const { addToCart } = useCart();
  const navigate = useNavigate();
  const [heroRef, heroVisible] = useInView();

  const loadOffers = useCallback(async () => {
    try {
      const { data } = await productAPI.getAll({ status: 'published', limit: 100 });
      const all = data.products || data;
      const now = new Date();
      const filtered = all.filter(p =>
        p.specialOffer?.enabled &&
        (!p.specialOffer.endsAt || new Date(p.specialOffer.endsAt) > now)
      );
      setOffers(filtered);
    } catch {}
    setLoading(false);
  }, []);

  useEffect(() => { loadOffers(); }, [loadOffers]);

  const handleAdd = (product) => {
    const price = product.specialOffer?.salePrice || product.price;
    addToCart({ ...product, price });
    toast.success(`🎉 ${product.name} added to cart!`);
  };

  return (
    <div style={{ minHeight: '80vh' }}>
      {/* Hero */}
      <div ref={heroRef} style={{ background: 'linear-gradient(135deg,#c2185b,#e91e63,#ff6090)', padding: '60px 20px', textAlign: 'center', color: 'white', opacity: heroVisible ? 1 : 0, transform: heroVisible ? 'translateY(0)' : 'translateY(30px)', transition: 'all 0.7s ease' }}>
        <div style={{ fontSize: 48, marginBottom: 12 }}>🔥</div>
        <h1 style={{ fontSize: 'clamp(26px,5vw,42px)', fontWeight: 900, marginBottom: 10 }}>Special Offers</h1>
        <p style={{ fontSize: 16, opacity: 0.9, maxWidth: 500, margin: '0 auto' }}>Flash deals, exclusive discounts and limited-time offers just for you</p>
      </div>

      <div className="container" style={{ padding: '40px 20px' }}>
        {loading ? (
          <div style={{ textAlign: 'center', padding: 60, color: '#636e72' }}>Loading deals...</div>
        ) : offers.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 20px' }}>
            <div style={{ fontSize: 60, marginBottom: 16 }}>🎁</div>
            <h2 style={{ fontWeight: 700, color: '#212121', marginBottom: 8 }}>No active deals right now</h2>
            <p style={{ color: '#636e72', marginBottom: 24 }}>Check back soon — new offers drop every week!</p>
            <button className="btn btn-primary" onClick={() => navigate('/products')}>Shop All Products</button>
          </div>
        ) : (
          <>
            <div style={{ textAlign: 'center', marginBottom: 32 }}>
              <span style={{ background: '#fce4ec', color: '#c2185b', fontWeight: 700, padding: '6px 18px', borderRadius: 20, fontSize: 14 }}>
                🔥 {offers.length} active deal{offers.length !== 1 ? 's' : ''} available
              </span>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(260px,1fr))', gap: 24 }}>
              {offers.map(product => {
                const originalPrice = product.price;
                const salePrice     = product.specialOffer.salePrice || originalPrice;
                const savePct       = originalPrice > salePrice ? Math.round((1 - salePrice / originalPrice) * 100) : 0;
                return (
                  <div key={product._id} style={{ background: 'white', borderRadius: 20, overflow: 'hidden', boxShadow: '0 4px 20px rgba(194,24,91,0.12)', border: '2px solid #f8bbd0', transition: 'transform 0.25s, box-shadow 0.25s' }}
                    onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-4px)'; e.currentTarget.style.boxShadow = '0 12px 32px rgba(194,24,91,0.22)'; }}
                    onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = '0 4px 20px rgba(194,24,91,0.12)'; }}>
                    {/* Badge + image */}
                    <div style={{ position: 'relative', cursor: 'pointer' }} onClick={() => navigate(`/products/${product._id}`)}>
                      <img src={product.images?.[0] || '/placeholder.png'} alt={product.name}
                        style={{ width: '100%', height: 220, objectFit: 'cover' }} />
                      {savePct > 0 && (
                        <div style={{ position: 'absolute', top: 12, left: 12, background: '#d63031', color: 'white', fontWeight: 800, padding: '4px 12px', borderRadius: 20, fontSize: 14 }}>
                          -{savePct}% OFF
                        </div>
                      )}
                      {product.specialOffer.label && (
                        <div style={{ position: 'absolute', top: 12, right: 12, background: '#c2185b', color: 'white', fontWeight: 700, padding: '4px 10px', borderRadius: 10, fontSize: 11 }}>
                          {product.specialOffer.label}
                        </div>
                      )}
                    </div>

                    <div style={{ padding: '16px 18px' }}>
                      <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 4, color: '#212121', cursor: 'pointer' }} onClick={() => navigate(`/products/${product._id}`)}>
                        {product.name}
                      </div>
                      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 8 }}>
                        <span style={{ fontSize: 22, fontWeight: 900, color: '#c2185b' }}>₹{salePrice.toLocaleString()}</span>
                        {savePct > 0 && <span style={{ fontSize: 14, color: '#9e9e9e', textDecoration: 'line-through' }}>₹{originalPrice.toLocaleString()}</span>}
                      </div>
                      {product.specialOffer.endsAt && (
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12, background: '#fff8f9', borderRadius: 10, padding: '8px 12px' }}>
                          <span style={{ fontSize: 12, color: '#636e72', fontWeight: 600 }}>⏰ Ends in:</span>
                          <CountdownTimer endsAt={product.specialOffer.endsAt} />
                        </div>
                      )}
                      <button
                        onClick={() => handleAdd(product)}
                        disabled={product.stock <= 0}
                        className="btn btn-primary"
                        style={{ width: '100%', padding: '10px 0' }}>
                        {product.stock <= 0 ? 'Out of Stock' : '🛒 Add to Cart'}
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>
    </div>
  );
}
